//! Local reminder scheduling. Persist the delivery marker before presenting a banner.
use serde::{Serialize,Deserialize};use serde_json::{Value,json};use std::path::PathBuf;
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(rename_all="camelCase")]
pub struct Todo{pub id:String,pub title:String,pub content:String,pub date:String,pub time:String,pub daily:bool,#[serde(default="default_color")]pub color:String,#[serde(default)]pub completed:bool,#[serde(default)]pub completed_date:Option<String>,#[serde(default)]pub last_reminded_date:Option<String>,#[serde(default)]pub snooze_until:Option<String>}
pub fn default_color()->String{"#F3D79B".into()}
#[derive(Clone,Debug)]pub struct Now{pub date:String,pub time:String}
impl Now{pub fn local()->Self{let t=unsafe{windows::Win32::System::SystemInformation::GetLocalTime()};Self{date:format!("{:04}-{:02}-{:02}",t.wYear,t.wMonth,t.wDay),time:format!("{:02}:{:02}",t.wHour,t.wMinute)}}}
pub fn valid_date(s:&str)->bool{let b=s.as_bytes();if b.len()!=10||b[4]!=b'-'||b[7]!=b'-'||!b.iter().enumerate().all(|(i,c)|i==4||i==7||c.is_ascii_digit()){return false}let y=s[0..4].parse::<u32>().unwrap_or(0);let m=s[5..7].parse::<u32>().unwrap_or(0);let d=s[8..10].parse::<u32>().unwrap_or(0);let max=match m{1|3|5|7|8|10|12=>31,4|6|9|11=>30,2=>if y%400==0||(y%4==0&&y%100!=0){29}else{28},_=>0};(1900..=9999).contains(&y)&&d>0&&d<=max}
pub fn valid_time(s:&str)->bool{let b=s.as_bytes();b.len()==5&&b[2]==b':'&&b.iter().enumerate().all(|(i,c)|i==2||c.is_ascii_digit())&&s[..2].parse::<u32>().unwrap_or(99)<24&&s[3..].parse::<u32>().unwrap_or(99)<60}
fn days_in_month(y:u32,m:u32)->u32{match m{1|3|5|7|8|10|12=>31,4|6|9|11=>30,2=>if y%400==0||(y%4==0&&y%100!=0){29}else{28},_=>30}}
/// Add whole minutes to a local `YYYY-MM-DD`/`HH:MM` pair, carrying across days, months and years.
pub fn add_minutes(date:&str,time:&str,minutes:u32)->String{
 let (mut y,mut m)=(date[0..4].parse::<u32>().unwrap_or(2000),date[5..7].parse::<u32>().unwrap_or(1));
 let total=time[..2].parse::<u32>().unwrap_or(0)*60+time[3..].parse::<u32>().unwrap_or(0)+minutes;
 let extra=total/1440;let rest=total%1440;let mut target=date[8..10].parse::<u32>().unwrap_or(1)+extra;
 while target>days_in_month(y,m){target-=days_in_month(y,m);m+=1;if m>12{m=1;y+=1}}
 format!("{:04}-{:02}-{:02} {:02}:{:02}",y,m,target,rest/60,rest%60)
}
impl Todo{pub fn done(&self,now:&Now)->bool{self.completed&&(!self.daily||self.completed_date.as_deref()==Some(&now.date))}fn due(&self,n:&Now)->bool{if self.done(n){return false}if let Some(until)=&self.snooze_until{return until.as_str()<=format!("{} {}",n.date,n.time).as_str()}if self.date>n.date{return false}if self.daily{self.time<=n.time&&self.last_reminded_date.as_ref()!=Some(&n.date)}else{self.last_reminded_date.is_none()&&(self.date<n.date||self.time<=n.time)}}}
pub struct Store{path:PathBuf,pub items:Vec<Todo>,pub error:Option<String>}
impl Store{
 pub fn new(path:PathBuf)->Self{let (items,error)=if path.is_file(){match std::fs::read_to_string(&path).map_err(|e|e.to_string()).and_then(|s|serde_json::from_str::<Vec<Todo>>(&s).map_err(|e|e.to_string())){Ok(items)=>(items,None),Err(e)=>(vec![],Some(format!("待办文件读取失败，原文件保留：{e}")))}}else{(vec![],None)};Self{path,items,error}}
 fn persist(&mut self,old:Vec<Todo>)->Result<(),String>{if let Some(e)=&self.error{self.items=old;return Err(e.clone())}if let Err(e)=lyric_backend::io::save_settings(&self.path,&json!(self.items)){self.items=old;return Err(e)}Ok(())}
 pub fn list(&self,n:&Now)->Value{json!(self.items.iter().map(|t|{let mut v=json!(t);v["completed"]=json!(t.done(n));v}).collect::<Vec<_>>())}
 pub fn save(&mut self,v:&Value)->Result<String,String>{
  let text=|key:&str,max:usize|->Result<String,String>{let s=v[key].as_str().unwrap_or("").trim();if s.chars().count()>max||s.chars().any(|c|c.is_control()&&c!='\n'){return Err(format!("{key} 内容过长或包含无效字符"))}Ok(s.to_owned())};
  let title=text("title",120)?;if title.is_empty(){return Err("请填写待办题目".into())}let content=text("content",2048)?;let date=text("date",10)?;let time=text("time",5)?;if !valid_date(&date){return Err("日期请填写为有效的 YYYY-MM-DD".into())}if !valid_time(&time){return Err("时间请填写为 24 小时制 HH:MM".into())}
  let requested=v["id"].as_str().unwrap_or("");if requested.len()>80||!requested.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'){return Err("待办标识无效".into())}
  let id=if requested.is_empty(){format!("todo-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos())}else{requested.into()};let daily=v["daily"].as_bool().unwrap_or(false);let color=v["color"].as_str().unwrap_or("#F3D79B");if color.len()!=7||!color.starts_with('#')||!color[1..].bytes().all(|b|b.is_ascii_hexdigit()){return Err("待办颜色格式无效".into())}let color=color.to_uppercase();let old=self.items.clone();
  if let Some(t)=self.items.iter_mut().find(|t|t.id==id){if t.date!=date||t.time!=time||t.daily!=daily{t.last_reminded_date=None;t.snooze_until=None;}t.title=title;t.content=content;t.date=date;t.time=time;t.daily=daily;t.color=color;}
  else{if self.items.len()>=256{return Err("最多保存 256 条待办，请先清理已完成项目".into())}self.items.push(Todo{id:id.clone(),title,content,date,time,daily,color,completed:false,completed_date:None,last_reminded_date:None,snooze_until:None});}
  self.persist(old)?;Ok(id)
 }
 pub fn complete(&mut self,id:&str,done:bool,n:&Now)->Result<(),String>{let old=self.items.clone();let t=self.items.iter_mut().find(|t|t.id==id).ok_or("待办不存在")?;t.completed=done;t.completed_date=if done{Some(n.date.clone())}else{None};t.snooze_until=None;self.persist(old)}
 /// Postpone the next reminder. Uses the later of the scheduled moment and now, so cancelling a
 /// banner always waits the full delay while a future reminder is only nudged past its own time.
 /// The delivery marker is set here; the original rule stays untouched for daily repeats.
 pub fn snooze(&mut self,id:&str,minutes:u32,n:&Now)->Result<(),String>{
  if !matches!(minutes,10|60){return Err("稍后提醒仅支持 10 分钟或 1 小时".into())}
  let old=self.items.clone();let t=self.items.iter_mut().find(|t|t.id==id).ok_or("待办不存在")?;
  if t.done(n){return Err("已完成的待办无需再次提醒".into())}
  let (date,time)=if format!("{} {}",t.date,t.time)<=format!("{} {}",n.date,n.time){(n.date.as_str(),n.time.as_str())}else{(t.date.as_str(),t.time.as_str())};
  t.snooze_until=Some(add_minutes(date,time,minutes));t.last_reminded_date=Some(n.date.clone());self.persist(old)
 }
 pub fn restore(&mut self,value:&Value)->Result<(),String>{
  let todo:Todo=serde_json::from_value(value.clone()).map_err(|e|e.to_string())?;if self.items.iter().any(|t|t.id==todo.id){return Err("待办已存在".into())}if self.items.len()>=256||!valid_date(&todo.date)||!valid_time(&todo.time)||todo.title.trim().is_empty()||todo.title.chars().count()>120||todo.id.len()>80||!todo.id.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'){return Err("待办内容无效".into())}let old=self.items.clone();self.items.push(todo);self.persist(old)
 }
 pub fn delete(&mut self,id:&str)->Result<(),String>{let old=self.items.clone();if !self.items.iter().any(|t|t.id==id){return Err("待办不存在".into())}self.items.retain(|t|t.id!=id);self.persist(old)}
 pub fn poll(&mut self,n:&Now)->Result<Vec<Todo>,String>{let old=self.items.clone();let mut due=vec![];for t in &mut self.items{if t.due(n){if t.snooze_until.is_some(){t.snooze_until=None;}else{t.last_reminded_date=Some(n.date.clone());}due.push(t.clone());}}if !due.is_empty(){self.persist(old)?;}Ok(due)}
}
#[cfg(test)]mod tests{use super::*;fn fixture()->(Store,PathBuf){let p=std::env::temp_dir().join(format!("LyricIsland.TodoTest.{}.{}.json",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));(Store::new(p.clone()),p)}fn now(d:&str,t:&str)->Now{Now{date:d.into(),time:t.into()}}
 #[test]fn calendar_validation_including_leap_year(){assert!(valid_date("2028-02-29"));for d in ["2026-02-29","2026-13-01","2026-04-31","２０２６-01"]{assert!(!valid_date(d));}assert!(valid_time("09:03"));assert!(!valid_time("24:00"));}
 #[test]fn markers_survive_restart_and_daily_completion_resets_next_day(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"喝水","content":"休息一下","date":"2026-10-16","time":"09:00","daily":true})).unwrap();assert!(s.poll(&now("2026-10-16","08:59")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-16","09:00")).unwrap().len(),1);let mut s=Store::new(p.clone());assert!(s.poll(&now("2026-10-16","10:00")).unwrap().is_empty());s.complete(&id,true,&now("2026-10-16","10:00")).unwrap();assert!(!s.items[0].done(&now("2026-10-17","08:00")));assert_eq!(s.poll(&now("2026-10-17","09:00")).unwrap().len(),1);let _=std::fs::remove_file(p);}
 #[test]fn one_time_overdue_delivered_once_and_completed_never_alerts(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"交稿","date":"2026-10-15","time":"09:00"})).unwrap();s.complete(&id,true,&now("2026-10-16","10:00")).unwrap();assert!(s.poll(&now("2026-10-16","10:00")).unwrap().is_empty());s.complete(&id,false,&now("2026-10-16","10:00")).unwrap();assert_eq!(s.poll(&now("2026-10-16","10:00")).unwrap().len(),1);assert!(s.poll(&now("2026-10-17","10:00")).unwrap().is_empty());let _=std::fs::remove_file(p);}
 #[test]fn corrupt_store_is_never_overwritten(){let p=std::env::temp_dir().join(format!("LyricIsland.CorruptTodos.{}.json",std::process::id()));std::fs::write(&p,b"broken").unwrap();let mut s=Store::new(p.clone());assert!(s.save(&json!({"title":"x","date":"2026-10-16","time":"09:00"})).is_err());assert_eq!(std::fs::read(&p).unwrap(),b"broken");let _=std::fs::remove_file(p);}
 #[test]fn snooze_delivers_once_then_never_again_and_completion_cancels(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"交稿","date":"2026-10-15","time":"09:00"})).unwrap();s.snooze(&id,10,&now("2026-10-16","10:00")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-16 10:10"));assert!(s.poll(&now("2026-10-16","10:05")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-16","10:10")).unwrap().len(),1);assert!(s.poll(&now("2026-10-16","10:20")).unwrap().is_empty());s.snooze(&id,60,&now("2026-10-16","11:00")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-16 12:00"));s.complete(&id,true,&now("2026-10-16","11:00")).unwrap();assert!(s.items[0].snooze_until.is_none());assert!(s.poll(&now("2026-10-16","12:05")).unwrap().is_empty());let _=std::fs::remove_file(p);}
 #[test]fn snooze_of_a_future_reminder_only_delays_its_own_moment(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"取快递","date":"2026-10-16","time":"18:30"})).unwrap();s.snooze(&id,10,&now("2026-10-16","14:00")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-16 18:40"));assert!(s.poll(&now("2026-10-16","18:30")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-16","18:40")).unwrap().len(),1);assert!(s.poll(&now("2026-10-16","19:00")).unwrap().is_empty());let _=std::fs::remove_file(p);}
 #[test]fn cross_midnight_snooze_survives_restart_and_keeps_the_daily_cycle(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"记日记","date":"2026-10-16","time":"23:55","daily":true})).unwrap();assert_eq!(s.poll(&now("2026-10-16","23:55")).unwrap().len(),1);s.snooze(&id,10,&now("2026-10-16","23:55")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-17 00:05"));let mut s=Store::new(p.clone());assert!(s.poll(&now("2026-10-17","00:04")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-17","00:05")).unwrap().len(),1);assert!(s.poll(&now("2026-10-17","00:06")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-17","23:55")).unwrap().len(),1);let _=std::fs::remove_file(p);}
 #[test]fn snooze_rejects_unknown_delays_and_completed_items(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"x","date":"2026-10-16","time":"09:00"})).unwrap();assert!(s.snooze(&id,30,&now("2026-10-16","09:00")).is_err());assert!(s.snooze("missing",10,&now("2026-10-16","09:00")).is_err());s.complete(&id,true,&now("2026-10-16","09:00")).unwrap();assert!(s.snooze(&id,10,&now("2026-10-16","09:00")).is_err());let _=std::fs::remove_file(p);}
 #[test]fn editing_the_schedule_cancels_a_pending_snooze(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"x","date":"2026-10-16","time":"09:00"})).unwrap();s.snooze(&id,10,&now("2026-10-16","09:00")).unwrap();s.save(&json!({"id":id,"title":"x","date":"2026-10-16","time":"12:00"})).unwrap();assert!(s.items[0].snooze_until.is_none());assert_eq!(s.poll(&now("2026-10-16","12:00")).unwrap().len(),1);let _=std::fs::remove_file(p);}
 #[test]fn add_minutes_carries_days_months_and_leap_years(){assert_eq!(add_minutes("2026-10-16","23:55",10),"2026-10-17 00:05");assert_eq!(add_minutes("2026-10-31","23:55",60),"2026-11-01 00:55");assert_eq!(add_minutes("2026-12-31","23:30",60),"2027-01-01 00:30");assert_eq!(add_minutes("2028-02-28","23:55",10),"2028-02-29 00:05");assert_eq!(add_minutes("2027-02-28","23:55",10),"2027-03-01 00:05");}
}
